def split_labor_articles(apps, schema_editor):
    LaborArticle = apps.get_model("orders", "LaborArticle")
    Job = apps.get_model("orders", "Job")
    WorkOrder = apps.get_model("orders", "WorkOrder")
    db = schema_editor.connection.alias
    mapping = {}
    originals = list(LaborArticle.objects.using(db).all())
    for article in originals:
        mapping[(article.pk, "standard")] = article.pk
        LaborArticle.objects.using(db).filter(pk=article.pk).update(
            tariff_type="standard", hourly_rate=article.standard_rate
        )
        for tariff_type, suffix, rate in (
            ("holiday", "FEST", article.holiday_rate),
            ("discounted", "SCONT", article.discounted_rate),
        ):
            root = article.code[:40 - len(suffix) - 1]
            code = f"{root}-{suffix}"
            counter = 1
            while LaborArticle.objects.using(db).filter(workshop_id=article.workshop_id, code=code).exists():
                tail = f"-{counter}"
                code = f"{root[:40-len(suffix)-len(tail)-1]}-{suffix}{tail}"
                counter += 1
            clone = LaborArticle.objects.using(db).create(
                workshop_id=article.workshop_id,
                code=code,
                description=article.description,
                tariff_type=tariff_type,
                hourly_rate=rate,
                is_active=article.is_active,
            )
            mapping[(article.pk, tariff_type)] = clone.pk

    # Preserve the tariff previously selected on existing work orders by
    # moving each job to the matching split article before removing the header.
    for job in Job.objects.using(db).select_related("work_order").iterator():
        if job.labor_article_id:
            tariff_type = job.work_order.tariff_type or "standard"
            job.labor_article_id = mapping.get((job.labor_article_id, tariff_type), job.labor_article_id)
            job.save(update_fields=("labor_article",))


